// Subsetted variable fonts (generated by scripts/subset-fonts.py → fontdata.ts) — zero tofu, offline & deterministic.
import { continueRender, delayRender, staticFile } from "remotion";
import { useEffect, useState } from "react";
import { FONT_DATA } from "./fontdata";

const FACES: [string, keyof typeof FONT_DATA, string, string][] = [
  ["UnravelSerif", "serif", "600 900", "normal"],
  ["UnravelSans", "sans", "500 900", "normal"],
  ["UnravelGaramond", "garamond", "400 800", "italic"],
  ["UnravelMono", "mono", "100 800", "normal"],
];

let pending: Promise<void> | null = null;

export function loadFonts(): Promise<void> {
  if (pending) return pending;
  if (typeof document === "undefined" || typeof FontFace === "undefined") return Promise.resolve();
  pending = Promise.all(
    FACES.map(async ([family, key, weight, style]) => {
      try {
        const face = new FontFace(family, `url(data:font/woff2;base64,${FONT_DATA[key]}) format('woff2')`, { weight, style });
        await face.load();
        document.fonts.add(face);
      } catch {
        /* falls back to system CJK fonts */
      }
    }),
  ).then(() => undefined);
  return pending;
}

/** Holds the Remotion render until every embedded face is registered. */
export function useFonts(): boolean {
  const [handle] = useState(() => delayRender("film-fonts"));
  const [ready, setReady] = useState(false);
  useEffect(() => {
    loadFonts().finally(() => {
      setReady(true);
      continueRender(handle);
    });
  }, [handle]);
  return ready;
}

/** Audio URL that works in the Remotion renderer (staticFile) and in the Vite-served Player preview (relative to the page). */
export function audioUrl(name: string): string {
  if (typeof window !== "undefined" && (window as unknown as { remotion_isPlayer?: boolean }).remotion_isPlayer) {
    return new URL(`audio/${name}`, document.baseURI).href;
  }
  return staticFile(`audio/${name}`);
}
